def sitebtn(label,id,secondary=False):return f'<div id="{id}" class="sitebtn'+(' secondary' if secondary else '')+'">'+label+'</div>'
def field(value,id,top,placeholder=False,area=False):return f'<div id="{id}" class="webfield'+(' empty' if placeholder else '')+(' area' if area else '')+f'" style="top:{top}px">{value}</div>'
def label(text,top):return f'<label style="top:{top}px">{text}</label>'
def orgsite(kind,modal='',result=''):
 items=['General','API keys','Admin keys','People','Projects','Billing','Limits','Tunnels','Usage','Service health','Data controls','Security','Webhooks']
 side='<aside class="site-side"><div class="back">←　Back to project</div>'+''.join('<div class="navitem'+(' active' if x==kind else '')+'">'+x+'</div>' for x in items)+'<div class="org">D　Demo organization</div></aside>'
 head='<header class="site-head"><h2>'+kind+'</h2>'+sitebtn('Create tunnel' if kind=='Tunnels' else '+ Create new secret key','opencreate')+'</header>'
 body='<div class="site-search">⌕　Search…</div><div class="site-empty"><strong>'+('No tunnels yet' if kind=='Tunnels' else 'Create an API key to access the OpenAI API')+'</strong>'+('Create your first tunnel to connect MCP servers behind a firewall.' if kind=='Tunnels' else '')+'</div>'
 return '<div class="window"><div class="browserbar"><span class="dots">●●●</span>platform.openai.com/settings/organization/'+('tunnels' if kind=='Tunnels' else 'api-keys')+'</div><div class="site">'+side+head+(result or body)+'</div>'+modal+'</div>'
def tunnelmodal(name='',description='',ws=False,menu=False):
 c='<div class="webshade"><div class="webmodal"><h3>Create tunnel</h3><span class="close">×</span>'
 c+=label('Name <span class="req">*</span>',60)+field(name or 'e.g. West Coast MCP tunnel','tunnelname',81,not name)
 c+=label('Description <span class="req">*</span>',128)+field(description or 'Add a short description to help your team.','description',149,not description,True)+'<div class="hint" style="top:216px">Required. Add a short description to help your team.</div>'
 c+=label('Organizations',247)+field('<span class="tag">Demo organization</span>　⌄','organization',267)+'<div class="hint" style="top:308px">Select one or more organizations, or search for an exact organization ID.</div>'
 c+=label('ChatGPT workspaces',339)+field(('<span class="tag">'+WORKSPACE+'</span>' if ws else 'Search workspaces by name or ID')+'　⌄','workspace',359,not ws)
 # Keep exact labels, with Security below the selection on the final scene.
 c+='<div class="hint" style="top:399px">Select ChatGPT workspaces, or search for an exact workspace ID.</div>'
 c+='<div class="security" style="top:431px">Optional security<br><br><span class="webcheck"></span>Restrict client network access</div>'
 # Current network restriction is not shown in older reference captures.
 if menu:c+='<div class="menu-pop" style="top:398px"><div class="search">⌕ Search workspaces by name or ID</div><div id="selectworkspace" class="option">'+WORKSPACE+'</div></div>'
 c+='<div class="modal-foot">'+sitebtn('Cancel','cancel',True)+sitebtn('Create','create')+'</div></div></div>';return c

def tunnelresult(copied=False):
 # Reference-backed row layout. Every value, including the workspace UUID, is synthetic.
 headers=''.join('<span style="position:absolute;left:'+str(x)+'px">'+title+'</span>' for x,title in [(0,'TUNNEL'),(130,'ID'),(495,'ORGANIZATIONS'),(640,'WORKSPACES'),(880,'CREATED BY')])
 row='<div style="position:absolute;left:0;top:57px"><strong>Farol Demo</strong><br><span style="color:#657080">Demo Mac access</span></div>'
 row+='<div style="position:absolute;left:130px;top:67px;font-size:11px">'+TUNNEL+'</div>'
 row+='<div style="position:absolute;left:365px;top:57px">'+sitebtn('Copied' if copied else 'Copy','copy',True)+'</div>'
 row+='<div style="position:absolute;left:495px;top:67px">Demo organization</div>'
 row+='<div style="position:absolute;left:640px;top:67px;font:10px monospace">'+WORKSPACE+'</div>'
 row+='<div style="position:absolute;left:880px;top:67px">Demo user</div>'
 table='<div style="position:absolute;left:230px;top:82px;width:984px"><div style="padding:11px 15px;background:#e9f6ee;color:#27613e;border-radius:6px;display:inline-block;font-size:12px">Tunnel created successfully.</div><div role="table" style="position:relative;width:984px;height:130px;margin-top:25px;font-size:11px"><div style="height:40px;border-bottom:1px solid #dce0e7;color:#606b7b;font-size:10px;font-weight:bold">'+headers+'</div>'+row+'</div><p style="margin-top:16px;color:#6b617a;font-size:12px">Recreated result row · Synthetic values only</p></div>'
 return orgsite('Tunnels',result=table)

def keysaved(copied=False):
 c='<div class="webshade"><div class="webmodal keymodal" style="top:117px;height:425px"><h3>Save your key</h3><p style="position:absolute;left:22px;top:60px;width:474px;font-size:13px;line-height:1.6;color:#606b7b">Please save your secret key in a safe place since you won’t be able to view it again. Keep it secure, as anyone with your API key can make requests on your behalf.</p><div style="position:absolute;left:22px;top:174px;font-size:12px;color:#586778;text-decoration:underline">Learn more about API key best practices ↗</div><div class="copyline" style="position:absolute;top:188px;left:22px;width:474px;margin:22px 0">DEMO_KEY_NOT_VALID'+sitebtn('Copied' if copied else 'Copy','copy')+'</div><div style="position:absolute;left:22px;top:292px;font-size:12px">Permissions</div><div style="position:absolute;left:22px;top:318px;font-size:12px;color:#586778">Tunnels: Read + Use only</div><div class="modal-foot">'+sitebtn('Done','keydone')+'</div></div></div>'
 return orgsite('API keys',c)

def resultpanel(title,text,value,copylabel='Copy',sub=''):
 return '<div class="window"><div class="site" style="top:0;height:652px"><div class="illustration-result"><div class="eyebrow">ILLUSTRATIVE RESULT · SYNTHETIC VALUES</div><h2>'+title+'</h2><p>'+text+'</p><div class="copyline">'+value+(sitebtn(copylabel,'copy') if copylabel else '')+'</div><p>'+sub+'</p><p class="result-note">A recreated example, not a live account result.</p></div></div></div>'
def add(name,title,step,caption,window,note='UI recreation · Synthetic data · Not a live setup test'):
 h='<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="shell.css"><link rel="stylesheet" href="setup.css"><link rel="stylesheet" href="demo.css"><link rel="stylesheet" href="remaining.css"></head><body><div class="story"><div class="brand"><img src="farol-sunrise.png">Farol<small>STEP-BY-STEP SETUP</small></div><div class="heading"><h1>'+title+'</h1><span>Follow the cursor</span></div>'+window+f'<div class="caption"><b>{step}</b>{caption}</div><div class="footer"><span>{note}</span><span>Farol · November 2026</span></div></div></body></html>'
 (R/(name+'.html')).write_text(h);SCENES.append(name)
def farolcontent(page,content,completed=2):
 titles={'connection':'Connect this Mac','attachment':'4. Add Farol to ChatGPT'};desc={'connection':'You need two things from OpenAI: a tunnel ID and its key.','attachment':'Create the app in ChatGPT with your tunnel, then test it end to end.'}
 n=nav(page,True)
 if completed>=2:n=n.replace('2 Workspaces','✓ Workspaces')
 if completed>=3:n=n.replace('3 Connect this Mac','✓ Connect this Mac')
 return '<div class="setup-wizard">'+n+f'<header class="setup-wizard-intro"><h1>{titles[page]}</h1><p class="description">{desc[page]}</p></header>'+content+'</div>'
def farolwin(page,content,completed=2):
 # Base shell only needs a breadcrumb mapping; replace it for attachment.
 html=shell(farolcontent(page,content,completed),'connection')
 if page=='attachment':html=html.replace('○　Not connected','●　Connected').replace('<span>Connect this Mac</span></div>','<span>Add to ChatGPT</span></div>')
 return html
walk='<h3>1. Create a tunnel and a key</h3><p class="description" style="margin-top:10px">Follow the steps below. You can return to any instruction.</p><div class="walk-cards"><div class="active"><strong>1　Create a tunnel</strong>On the Tunnels page</div><div><strong>2　Create a key</strong>Permission: Restricted</div><div><strong>3　Copy both here</strong>Tunnel ID and key</div></div><div class="walk-detail"><h4>1. Create a tunnel</h4><ol><li>Open OpenAI Tunnels and choose Create tunnel.</li><li>Give the tunnel a name you can recognize.</li><li>Choose the workspace that contains your ChatGPT app, then create the tunnel.</li></ol></div>'+button('Open OpenAI Tunnels','opentunnels','text-button')
add('t00','3. Create a tunnel',1,'In Farol, choose Open OpenAI Tunnels.',farolwin('connection',walk))
add('t01','3. Create a tunnel',2,'On the OpenAI Tunnels page, choose Create tunnel.',orgsite('Tunnels'))
add('t02','3. Create a tunnel',3,'Give this Mac’s tunnel a recognizable name.',orgsite('Tunnels',tunnelmodal()))
add('t03','3. Create a tunnel',3,'Give this Mac’s tunnel a recognizable name.',orgsite('Tunnels',tunnelmodal('Far')))
add('t04','3. Create a tunnel',4,'Add the required description. These are sample values.',orgsite('Tunnels',tunnelmodal('Farol Demo')))
add('t05','3. Create a tunnel',5,'Review the organization, then choose your ChatGPT workspace.',orgsite('Tunnels',tunnelmodal('Farol Demo','Connect my demo Mac to approved sample folders.')))
add('t06','3. Create a tunnel',5,'Choose your ChatGPT workspace. It may appear as an ID instead of a name.',orgsite('Tunnels',tunnelmodal('Farol Demo','Connect my demo Mac to approved sample folders.',menu=True)))
add('t07','3. Create a tunnel',6,'Review your selection and optional network restriction, then Create.',orgsite('Tunnels',tunnelmodal('Farol Demo','Connect my demo Mac to approved sample folders.',True)))
add('t08','3. Create a tunnel',7,'Copy the complete tunnel ID from its row. Use the same ID in Farol and ChatGPT.',tunnelresult(),note='Result layout recreated from supplied reference · All IDs are synthetic')
add('t09','3. Create a tunnel',7,'Before copying a key, return to Farol and paste this tunnel ID.',tunnelresult(True),note='Result layout recreated from supplied reference · All IDs are synthetic')


def keymodal(name='',restricted=False,permissions=None,menu=False):
 c='<div class="webshade"><div class="webmodal keymodal"><h3>Create new secret key</h3><span class="close">×</span>'
 if permissions is None:
  c+=label('Owned by',59)+'<div class="segments" style="top:78px"><span class="chosen">You</span><span>Service account</span></div><div class="intro">This API key is tied to your user and can make requests against the selected project.</div>'
  c+=label('Name <span style="color:#667080">Optional</span>',167)+field(name or 'My Test Key','keyname',187,not name)
  c+=label('Project',239)+field('Select project…　⌄','project',260,True)
  c+=label('Expiration',311)+field('Select an expiration　⌄','expiration',332,True)
  c+=label('Permissions',386)+'<div class="segments" style="top:408px"><span class="'+('' if restricted else 'chosen')+'">All</span><span id="restricted" class="'+('chosen' if restricted else '')+'">Restricted</span><span>Read only</span></div>'
 else:
  c+='<div class="permlist">'+''.join('<div class="permrow">'+x+'<span '+('id="tunnelpermissions" ' if x=='Tunnels' else '')+'class="permselect '+('chosen' if x=='Tunnels' else '')+'">'+('All selected' if permissions==2 and x=='Tunnels' else 'Read' if permissions==1 and x=='Tunnels' else 'None')+'　⌄</span></div>' for x in ['Fine-tuning','Files','Videos','Vector Stores','Prompts','Batch','Tunnels','Datasets','Safety'])+'</div><div class="small-scroll"></div><div class="permissioncount">'+str(permissions)+' selected permission'+('' if permissions==1 else 's')+'</div>'
  if menu:c+='<div class="permmenu" style="top:352px"><div id="readperm" class="'+('selected' if permissions>=1 else '')+'">'+('✓' if permissions>=1 else '　')+'　Read</div><div id="useperm" class="'+('selected' if permissions==2 else '')+'">'+('✓' if permissions==2 else '　')+'　Use</div></div>'
