def testwin(state='ready'):
 c='<div class="attach-info"><div><strong>Name</strong><div class="value">Farol<p>Use the exact name shown in ChatGPT. For a separate test app, use Farol Dev.</p></div></div><div><strong>Connection</strong><div class="value">Tunnel · '+TUNNEL+'</div></div><div><strong>App authentication</strong><div class="value">No additional sign-in<p>Choose None in the app’s authentication settings. Your ChatGPT account stays signed in separately.</p></div></div></div><h3>2. Check the connection</h3><p class="description" style="margin-top:10px">Farol opens a separate chat, selects Instant and sends one test message to your app. The reply confirms that ChatGPT can reach this Mac — without reading file contents.</p>'
 if state=='ready':c+=gate('Ready when your app is added','Add the app above, then run the check once.')+button('Test in ChatGPT','test')
 elif state=='running':c+=gate('Checking the connection…','Wait for the current test result.')+button('Testing in ChatGPT…','test','primary',True)
 else:c+=gate('ChatGPT is connected','ChatGPT reached this Mac and confirmed the approved workspace access.',True)+'<p class="setup-success"><strong>✓ Everything works</strong></p><p class="description" style="margin-top:8px">ChatGPT used Farol, reached this Mac and verified access to the approved workspace. No file contents were read.</p><footer class="setup-wizard-footer">'+button('Back','back','text-button')+button('Start using Farol','finish')+'</footer>'
 return farolwin('attachment',c,3).replace('<div class="setup-wizard">','<div class="setup-wizard" style="margin-top:-125px">')
